import { MessageRemoteImage, MessageState } from '../../logic/messages/messagesTypes';
import { querySelectorAll } from '../message/messageContent';
import { getRemoteImages, insertImageAnchor } from '../message/messageImages';
import {
    ATTRIBUTES_TO_FIND,
    ATTRIBUTES_TO_LOAD,
    hasToSkipProxy,
